fn bug20964_1() -> DrawResult<()> {
    let mut d = Draw::new();
    d.restore(&[data_file("OCC20964_revsolid.brep").as_str(), "b1"])?;
    d.restore(&[data_file("OCC20964_sphere.brep").as_str(), "b2"])?;
    d.bclearobjects(&[])?;
    d.bcleartools(&[])?;
    d.baddobjects(&["b1"])?;
    d.baddtools(&["b2"])?;
    d.bfillds(&[])?;
    d.bbop(&["result", "4"])?;
    d.checkprops(&["result", "-l", "323.635"])?;
    d.checkshape(&["result"])?;
    d.checksection(&["result", "-r", "0"])?;
    d.checknbshapes(&["result", "-ref", "\nNumber of shapes in .*\n VERTEX : 6\n EDGE : 6\n WIRE : 0\n FACE : 0\n SHELL : 0\n SOLID : 0\n COMPSOLID : 0\n COMPOUND : 1\n SHAPE : 13\n"])?;
    d.checkmaxtol(&["result", "-ref", "2.0849512334752456e-05"])?;
    Ok(())
}

