/// `tests/bugs/modalg_2/bug22770_4`
/// kentron: sub-shapes named by OCCT's enumeration are selected by position (draw_selectors.json)
#[test]
#[should_panic]
fn bug22770_4() {
    expected_failure(|| {
        let mut d = Draw::new();
        d.r#box(&["a", "1", "2", "3"])?;
        d.r#box(&["b", "2", "0", "0", "1", "2", "3"])?;
        d.explode(&["a", "f"])?;
        d.nearest(&["a_2", "a", "F", "1.0", "1.0", "1.5", "6.0"])?;
        d.explode(&["b", "f"])?;
        d.nearest(&["b_1", "b", "F", "2.0", "1.0", "1.5", "6.0"])?;
        d.sewing(&["result", "+t", "1.1", "a_2", "b_1", "-f"])?;
        d.checkprops(&["result", "-s", "12"])?;
        d.checkshape(&["result"])?;
        d.checknbshapes(&["result", "-vertex", "8", "-edge", "8", "-wire", "2", "-face", "2", "-shell", "0", "-solid", "0", "-compsolid", "0", "-compound", "1", "-shape", "21"])?;
        d.checkmaxtol(&["result", "-ref", "9.9999999999999995e-008"])?;
        d.checknbshapes(&["result", "-shell", "0"])?;
        d.checkfreebounds(&["result", "8"])?;
        Ok(())
    })
}

