#[test]
fn bug2785_1() -> DrawResult<()> {
    let mut d = Draw::new();
    d.pcylinder(&["c1", "2", "10"])?;
    d.pcylinder(&["c2", "2", "2"])?;
    d.explode(&["c1", "f"])?;
    d.nearest(&["c1_1", "c1", "F", "0.0", "-1.09629e-16", "5.0", "125.664"])?;
    d.explode(&["c2", "f"])?;
    d.nearest(&["c2_1", "c2", "F", "-4.44089e-16", "-1.09629e-16", "1.0", "25.1327"])?;
    d.mksurface(&["gs", "c2_1"])?;
    d.trim(&["trgs", "gs", "1", "2", "2", "4"])?;
    d.mkface(&["ff", "trgs"])?;
    d.trim(&["trgs", "gs", "0", "1", "2", "4"])?;
    d.mkface(&["ff2", "trgs"])?;
    d.bcut(&["rcut1", "c1_1", "ff"])?;
    d.checkshape(&["rcut1"])?;
    d.bop(&["ff2", "rcut1"])?;
    d.boptuc(&["rcut2"])?;
    d.checkshape(&["rcut2"])?;
    d.bfuse(&["fuse1", "rcut2", "ff2"])?;
    d.checkshape(&["fuse1"])?;
    d.bfuse(&["result", "fuse1", "ff"])?;
    d.checkprops(&["result", "-s", "125.664"])?;
    d.checkshape(&["result"])?;
    Ok(())
}

